fn ipv4_to_bytes(s: &str) -> Option<[u8; 4]> {
    let mut out = [0u8; 4];
    let mut n = 0usize;
    for part in s.split('.') {
        if n >= 4 {
            return None;
        }
        out[n] = part.parse::<u8>().ok()?;
        n += 1;
    }
    if n == 4 {
        Some(out)
    } else {
        None
    }
}

/// Plan E (ADR-0003, fix-1): build trustedIp as a read-only `table_data_set` from
/// running config so net-snmp serves GET/GETNEXT/GETBULK. Columns:
/// 1=index(INTEGER), 2=ipAddress(IPADDRESS), 3=netmask(IPADDRESS),
/// 4=rowStatus(INTEGER active(1)/notInService(2)). SET stays in-master; this is
/// GET-only. Built once at startup (PoC — refresh-on-config-change is future work).
fn register_trustedip_table(state: &SubagentState, root: &[agentx::Oid]) {
    let rows = match read_config_value(state, "trustedAccess/trustedIp") {
        Ok(v) => v.as_array().cloned().unwrap_or_default(),
        Err(_) => Vec::new(),
    };

    let tbl = agentx::table_new("trustedIpTable");
    if tbl.is_null() {
        return;
    }
    agentx::table_add_index(tbl, agentx::ASN_INTEGER);
    agentx::table_add_column(tbl, 1, agentx::ASN_INTEGER); // index
    agentx::table_add_column(tbl, 2, agentx::ASN_IPADDRESS); // ipAddress
    agentx::table_add_column(tbl, 3, agentx::ASN_IPADDRESS); // netmask
    agentx::table_add_column(tbl, 4, agentx::ASN_INTEGER); // rowStatus

    for (i, row) in rows.iter().enumerate() {
        let idx = (i + 1) as i64;
        let r = agentx::row_new();
        if r.is_null() {
            continue;
        }
        agentx::row_add_index_int(r, idx);
        agentx::row_set_col_int(r, 1, idx);
        if let Some(ip) = row.get("ipAddress").and_then(|v| v.as_str()).and_then(ipv4_to_bytes) {
            agentx::row_set_col_bytes(r, 2, agentx::ASN_IPADDRESS, &ip);
        }
        if let Some(mask) = row.get("netmask").and_then(|v| v.as_str()).and_then(ipv4_to_bytes) {
            agentx::row_set_col_bytes(r, 3, agentx::ASN_IPADDRESS, &mask);
        }
        // Mirror in-master / handle_rowstatus_get: valid==false -> notInService,
        // else (true or absent) -> active.
        let rs: i64 = match row.get("valid").and_then(|v| v.as_bool()) {
            Some(false) => RS_NOT_IN_SERVICE,
            _ => RS_ACTIVE,
        };
        agentx::row_set_col_int(r, 4, rs);
        agentx::table_add_row(tbl, r);
    }

    agentx::table_register(tbl, "trustedIpTable", root);
}

/// Start the AgentX subagent on its own thread (non-blocking). Registers every
/// mapped config OID read-only and connects to the snmpd master.
pub fn start_snmp_subagent(
    plugins: Arc<Mutex<Plugins>>,
    configs: Arc<Mutex<Configs>>,
    status_operation: Arc<Mutex<StatusOperation>>,
    plugins_status: Arc<Mutex<plugins_moxa_framework::status::Plugins>>,
) {
    let _ = STATE.set(SubagentState {
        plugins,
        configs,
        status_operation,
        plugins_status,
        status_snap: Mutex::new(StatusSnap {
            by_plugin: HashMap::new(),
        }),
    });

    agentx::init("app_moxa_framework");
    // Plan E fix-1 PoC: self-contained demo table_data_set at .8691.602.99.1 —
    // proves net-snmp serves GET/GETNEXT/GETBULK for a framework-owned table
    // (walk/bulkwalk .1.3.6.1.4.1.8691.602.99 should return 3 rows x 2 cols).
    const DEMO_TABLE: &[agentx::Oid] = &[1, 3, 6, 1, 4, 1, 8691, 602, 99, 1];
    agentx::register_demo_table(DEMO_TABLE);
    // Plan E (ADR-0003, fix-1): trustedIp served as ONE read-only table_data_set
    // (net-snmp sequences GET/GETNEXT/GETBULK); SET stays in-master. Its per-OID
    // regs are skipped below — the table_data_set owns the whole subtree.
    const TRUSTEDIP: &[agentx::Oid] = &[1, 3, 6, 1, 4, 1, 8691, 602, 1, 4, 1, 2];
    if let Some(st) = STATE.get() {
        register_trustedip_table(st, TRUSTEDIP);
    }
    for oid in lib_moxa_rust_ies_auto_mibs::all_oids() {
        let under_trustedip = oid.len() > TRUSTEDIP.len()
            && oid.iter().zip(TRUSTEDIP.iter()).all(|(a, b)| a == b);
        if under_trustedip {
            continue; // served by the table_data_set built above
        }
        agentx::register_instance(
            "moxaIesConfig",
            &oid,
            agentx::HANDLER_CAN_RWRITE,
            moxa_config_handler,
        );
    }
    agentx::run_in_thread();
}

