 * GET/GETNEXT/GETBULK entirely — this proves a forwarded walk/bulkwalk into a
 * framework-owned table works before we map real config data. Priority 200 so
 * in-master (127) still wins the wire (dual-reg). Returns 0 on success. */
int
MoxaAgentX_RegisterDemoTable(const oid *root, size_t root_len)
{
    netsnmp_table_data_set       *tds;
    netsnmp_handler_registration *reg;
    int                           i;

    tds = netsnmp_create_table_data_set("moxaDemoTable");
    if (tds == NULL)
    {
        return -1;
    }
    netsnmp_table_dataset_add_index(tds, ASN_INTEGER);           /* index: INTEGER */
    netsnmp_table_set_add_default_row(tds, 1, ASN_INTEGER,   0, NULL, 0);
    netsnmp_table_set_add_default_row(tds, 2, ASN_OCTET_STR, 0, NULL, 0);

    for (i = 1; i <= 3; i++)
    {
        netsnmp_table_row *row = netsnmp_create_table_data_row();
        long               idx = i;
        long               val = i * 10;
        char               buf[16];
        int                n;

        if (row == NULL)
        {
            return -1;
        }
        netsnmp_table_row_add_column(row, ASN_INTEGER, &idx, sizeof(idx));   /* index */
        netsnmp_set_row_column(row, 1, ASN_INTEGER, (const void *) &val, sizeof(val));
        n = snprintf(buf, sizeof(buf), "row-%d", i);
        netsnmp_set_row_column(row, 2, ASN_OCTET_STR, (const void *) buf, (size_t) n);
        netsnmp_table_dataset_add_row(tds, row);
    }

    reg = netsnmp_create_handler_registration("moxaDemoTable", NULL,
                                              root, root_len, HANDLER_CAN_RONLY);
    if (reg == NULL)
    {
        return -1;
    }
    reg->priority = 200;
    return netsnmp_register_table_data_set(reg, tds, NULL);
}

/* Plan E fix-1: generic read-only table_data_set builder (Rust drives it with
 * real config rows). Usage: TableNew -> TableAddIndex(es) -> TableAddColumn(s) ->
 * per row: RowNew -> RowAddIndex(es) -> RowSetCol(s) -> TableAddRow -> finally
 * TableRegister. `asn_type` is a net-snmp ASN_* (INTEGER/OCTET_STR/IPADDRESS...).
 * Handles are opaque; net-snmp serves GET/GETNEXT/GETBULK. */
void *
MoxaAgentX_TableNew(const char *name)
{
    return (void *) netsnmp_create_table_data_set(name);
}

int
MoxaAgentX_TableAddIndex(void *tbl, int asn_type)
{
    if (tbl == NULL) return -1;
    netsnmp_table_dataset_add_index((netsnmp_table_data_set *) tbl, (u_char) asn_type);
    return 0;
}

int
MoxaAgentX_TableAddColumn(void *tbl, unsigned int col, int asn_type)
{
    if (tbl == NULL) return -1;
    /* writable = 0: read-only (SET stays in-master under Plan E). */
    return netsnmp_table_set_add_default_row((netsnmp_table_data_set *) tbl,
                                             col, asn_type, 0, NULL, 0);
}

void *
MoxaAgentX_RowNew(void)
{
    return (void *) netsnmp_create_table_data_row();
}

int
MoxaAgentX_RowAddIndex(void *row, int asn_type, const void *val, size_t len)
{
    /* Typed local: the netsnmp_table_row_add_column macro does `row->indexes`
     * without parenthesizing `row`, so a cast expression would mis-parse. */
    netsnmp_table_row *r = (netsnmp_table_row *) row;
    if (r == NULL) return -1;
    netsnmp_table_row_add_column(r, asn_type, (void *) val, len);
    return 0;
}

int
MoxaAgentX_RowSetCol(void *row, unsigned int col, int asn_type,
                     const void *val, size_t len)
{
    if (row == NULL) return -1;
    return netsnmp_set_row_column((netsnmp_table_row *) row, col, asn_type,
                                  val, len);
}

int
MoxaAgentX_TableAddRow(void *tbl, void *row)
{
    if (tbl == NULL || row == NULL) return -1;
    netsnmp_table_dataset_add_row((netsnmp_table_data_set *) tbl,
                                  (netsnmp_table_row *) row);
    return 0;
}

int
MoxaAgentX_TableRegister(void *tbl, const char *name,
                         const oid *root, size_t root_len)
{
    netsnmp_handler_registration *reg;

    if (tbl == NULL) return -1;
    reg = netsnmp_create_handler_registration(name, NULL, root, root_len,
                                              HANDLER_CAN_RONLY);
    if (reg == NULL) return -1;
    reg->priority = 200;   /* in-master (127) wins the wire; framework serves GET */
    return netsnmp_register_table_data_set(reg, (netsnmp_table_data_set *) tbl, NULL);
}

