/* Forward a single GET/GETNEXT request to the ISS AgentX subagent, bypassing
 * the slow local ies_uri_handle path. agentx_master_handler marks the request
 * delegated and sends it async; net-snmp fills the value when ISS replies.
 * Returns 0 if handed to ISS, -1 if ISS is not registered (caller falls back). */
static int
mox_snmp_forward_get_to_iss (const struct mox_iss_get_forward_rule *rule,
                             netsnmp_agent_request_info *reqinfo,
                             netsnmp_request_info       *request)
{
    netsnmp_subtree      *iss_sub;
    netsnmp_request_info *saved_next;

    iss_sub = netsnmp_subtree_find(rule->probe_oid, rule->probe_oid_len,
                                   NULL, NULL);
    if ( iss_sub == NULL || iss_sub->reginfo == NULL ||
         iss_sub->reginfo->handler == NULL )
    {
        return -1;                      /* ISS AgentX subagent not connected */
    }

    /* Forward only THIS request; detach siblings so netsnmp_call_handlers does
     * not pull the rest of the chain (this handler is invoked per request). */
    saved_next    = request->next;
    request->next = NULL;
    (void) netsnmp_call_handlers(iss_sub->reginfo, reqinfo, request);
    request->next = saved_next;

    return 0;
}

/* Plan E PoC (ADR-0003): forward a trustedIp-table GET to the framework AgentX
 * subagent. Unlike the ISS path (probe OID), here in-master AND framework
 * dual-register the SAME OID, so we locate framework's registration by iterating
 * the subtrees covering this OID and picking the one whose handler is NOT our own
 * (mox_snmp_handle_entry). in-master wins the wire (priority 127 < framework 200);
 * this only runs for GET. Returns 0 if forwarded, -1 if framework not present. */
static const oid mox_trustedip_prefix[] = { 1,3,6,1,4,1,8691,602,1,4,1,2 };
#define MOX_TRUSTEDIP_PREFIX_LEN ((int)(sizeof(mox_trustedip_prefix)/sizeof(oid)))

static int
mox_snmp_entry_is_trustedip(struct ies_auto_mibs_entry *entry)
{
    int i;
    if ( entry->oid_len < MOX_TRUSTEDIP_PREFIX_LEN )
    {
        return 0;
    }
    for ( i = 0; i < MOX_TRUSTEDIP_PREFIX_LEN; i++ )
    {
        if ( (oid) entry->oid_list[i] != mox_trustedip_prefix[i] )
        {
            return 0;
        }
    }
    return 1;
}

static int
mox_snmp_forward_get_to_framework(struct ies_auto_mibs_entry *entry,
                                  netsnmp_agent_request_info *reqinfo,
                                  netsnmp_request_info       *request)
{
    netsnmp_subtree      *sub;
    netsnmp_subtree      *cand;
    netsnmp_request_info *saved_next;

    /* framework registers the table as ONE table_data_set at the TABLE ROOT
     * (mox_trustedip_prefix, .2), while in-master registers the deeper columns
     * (.2.1.c). Searching entry->oid_list (a column) never reaches framework's
     * table subtree — locate it at the table root, which framework owns
     * exclusively. Same-region priority variants are linked via ->children. */
    (void) entry;
    sub = netsnmp_subtree_find(mox_trustedip_prefix, MOX_TRUSTEDIP_PREFIX_LEN,
                               NULL, NULL);
    if ( sub == NULL )
    {
        return -1;
    }
    for ( cand = sub; cand != NULL; cand = cand->children )
    {
        if ( cand->reginfo != NULL && cand->reginfo->handler != NULL &&
             cand->reginfo->handler->access_method != mox_snmp_handle_entry )
        {
            saved_next    = request->next;
            request->next = NULL;
            (void) netsnmp_call_handlers(cand->reginfo, reqinfo, request);
            request->next = saved_next;
            return 0;
        }
    }
    return -1;                           /* framework subagent not present */
}

/*-------------------------------------------------------------------+
 * Function           : mox_snmp_handle_entry
 *
 * Description        :
        all the get function from ISS, use file operation.
        all function from framework use flask
        all the set function , use flask
+-------------------------------------------------------------------*/
int
mox_snmp_handle_entry
(
    netsnmp_mib_handler                   *handler,
    netsnmp_handler_registration          *reginfo,
    netsnmp_agent_request_info            *reqinfo,
    netsnmp_request_info                  *request 
)
{
    struct ies_auto_mibs_entry             entry_buf;
    struct ies_auto_mibs_entry            *entry = NULL;
    FILE                                  *fp    = NULL;
    int                                    ret;
    struct timespec                        timeBefore;
    struct timespec                        timeAfter;
    char                                   snmp_username[RWUSER_NAME_SIZE] = {0};
    int                                    token_cnt = 0;

    if ( request->processed )
    {
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%s line %d\n", __func__, __LINE__);
        return SNMP_ERR_NOERROR;
    }
    if ( 0 != clock_gettime(CLOCK_MONOTONIC, &timeBefore) ) 
    {
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
    }

    memset(&entry_buf, 0                   , sizeof(entry_buf));
    memcpy(&entry_buf, reginfo->my_reg_void, sizeof(entry_buf));

    entry = &entry_buf;

    if ( IES_AUTO_MIBS_MAGIC_ENTRY != entry->magic ) 
    {
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%s: Bad Magic \n", __func__);
        return SNMP_ERR_NOSUCHNAME; 
    }

    // Default token for snmp v1, v2c and v3(read-only user)
    snprintf(security_token, sizeof(security_token), "%s", security_tokens[0]);
    // Identify SNMPv3 read-write username and use different token to access
    if (reqinfo->asp->pdu->securityName)
    {
        snprintf(snmp_username, RWUSER_NAME_SIZE, reqinfo->asp->pdu->securityName);
        // Search token array
        for (token_cnt = 0; token_cnt < MAX_TOKEN_NUM - 1; token_cnt++) {
            if (strncmp(snmp_username, rwuser_list[token_cnt], RWUSER_NAME_SIZE) == 0) {
                memset(security_token, 0, sizeof(security_token));
                snprintf(security_token, sizeof(security_token), "%s", security_tokens[token_cnt+1]);
                break;
            }
        }
    }

    if ( MODE_IS_GET(reqinfo->mode) ) 
    {
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%s@%d: entry %s \n",
            __func__, __LINE__, entry->uri );

        /* Plan C (agentx_owned.list): RW column GET → ISS AgentX (fast); SET stays local. */
        {
            const struct mox_iss_get_forward_rule *fwd_rule =
                mox_snmp_entry_iss_get_forward_rule(entry);
            if ( fwd_rule != NULL )
            {
                if ( mox_snmp_forward_get_to_iss(fwd_rule, reqinfo, request) == 0 )
                {
                    return SNMP_ERR_NOERROR;
                }
                /* ISS unavailable → fall through to the local (slow) path */
            }
        }

        /* Plan E (ADR-0003, fix-1): trustedIp GET *and* GETNEXT → framework AgentX,
         * now that framework registers the table as a table_data_set (net-snmp
         * sequences GETNEXT/GETBULK — no longer weak). SET stays in-master.
         * Narrow hardcoded gate (PoC only). */
        if ( MODE_IS_GET(reqinfo->mode) && mox_snmp_entry_is_trustedip(entry) )
        {
            if ( mox_snmp_forward_get_to_framework(entry, reqinfo, request) == 0 )
            {
                return SNMP_ERR_NOERROR;
            }
            /* framework unavailable → fall through to local REST path */
        }

        if ( moxaSnmpHandle_ChkEntryGetValue(entry) == 0 )
        {
            if ( moxaSnmpHandle_ExeEntryGetValue(reqinfo, request, entry) == 0 )
            {
                return SNMP_ERR_NOERROR;
            }
            return SNMP_ERR_BADVALUE;
        }

