file.content:
void LibUtil_DbgTrace(const enum DebugFlagType aType,
                      char *aFormat, ...)
{
    /* Parse debug message from printf format string */
    va_list ap;
    char dbg_msg[LIB_UTIL_MAX_CMD_LEN];
    int32_t len = 0;

    /* if debug flag is unknown, print debug message to STDOUT */
    if (aType <= kDbgFlgInit || aType >= kDbgFlgRange) {
        _LibUtil_Dbg2File(LIB_UTIL_DBG_CTRL_LOG_FILE,
                        "Input error in %s:%d.\n", __func__, __LINE__);
        return;
    }

    /* control block debug message */
    if (aType == kDbgFlgCtrlBlk) {
        va_start(ap, aFormat);
        len = vsnprintf(dbg_msg, LIB_UTIL_MAX_CMD_LEN, aFormat, ap);
        va_end(ap);
        _LibUtil_Dbg2File(LIB_UTIL_DBG_CTRL_LOG_FILE, dbg_msg);
        return;
    }

    /* Check debug flag */
    if (LibUtil_CheckDbgFlgBits(aType)) {
        /* Prepare debug log file */
        char log_file[LIB_UTIL_MAX_FILE_NAME_LEN];
        FILE *fp = NULL;
        snprintf(log_file, LIB_UTIL_MAX_FILE_NAME_LEN,
                "%sdebug_log_%d", LIB_UTIL_DBG_PATH, aType);
        /* Put debug message to log file */
        fp  = fopen(log_file, "a+");
        if(fp != NULL){
            va_start(ap, aFormat);
            vfprintf(fp, aFormat, ap);
            va_end(ap);
            fflush(fp);
            fclose(fp);
        }
    }
}

