        register_trustedip_table(st, TRUSTEDIP);
    }
    for oid in lib_moxa_rust_ies_auto_mibs::all_oids() {
        let under_trustedip = oid.len() > TRUSTEDIP.len()
            && oid.iter().zip(TRUSTEDIP.iter()).all(|(a, b)| a == b);
        if under_trustedip {
            continue; // served by the table_data_set built above
