164	 * table_iterator. Unlike table_data_set (a one-time startup snapshot), the
165	 * iterator asks the framework for the CURRENT row count and column values on
166	 * every request, so SNMP GET/GETNEXT/GETBULK reflect config changes with no
167	 * reboot/refresh. C owns the net-snmp plumbing; Rust supplies row_count (stashed
168	 * in iinfo->myvoid) and the node handler (fills column values from live config).
169	 * Index = one INTEGER row number 1..count. Modeled on net-snmp vacm_context.c.
170	 * MoxaRowCountFn is declared in the public header. */
171	
172	static netsnmp_variable_list *
173	moxa_iter_get_first(void **loop_ctx, void **data_ctx,
174	                    netsnmp_variable_list *put_index,
175	                    netsnmp_iterator_info *iinfo)
176	{
177	    MoxaRowCountFn row_count = (MoxaRowCountFn) iinfo->myvoid;
178	    long           row = 1;
179	
180	    if (row_count == NULL || row_count() < 1)
181	    {
182	        return NULL;                 /* empty table -> clean endOfMibView */
183	    }
184	    *loop_ctx = (void *) (intptr_t) row;
185	    *data_ctx = (void *) (intptr_t) row;
186	    snmp_set_var_typed_value(put_index, ASN_INTEGER,
187	                             (const u_char *) &row, sizeof(row));
188	    return put_index;
189	}
190	
191	static netsnmp_variable_list *
192	moxa_iter_get_next(void **loop_ctx, void **data_ctx,
193	                   netsnmp_variable_list *put_index,
194	                   netsnmp_iterator_info *iinfo)
