/* Plan E PoC (ADR-0003): forward a trustedIp-table GET to the framework AgentX
 * subagent. Unlike the ISS path (probe OID), here in-master AND framework
 * dual-register the SAME OID, so we locate framework's registration by iterating
 * the subtrees covering this OID and picking the one whose handler is NOT our own
 * (mox_snmp_handle_entry). in-master wins the wire (priority 127 < framework 200);
 * this only runs for GET. Returns 0 if forwarded, -1 if framework not present. */
static const oid mox_trustedip_prefix[] = { 1,3,6,1,4,1,8691,602,1,4,1,2 };
#define MOX_TRUSTEDIP_PREFIX_LEN ((int)(sizeof(mox_trustedip_prefix)/sizeof(oid)))

static int
mox_snmp_entry_is_trustedip(struct ies_auto_mibs_entry *entry)
{
    int i;
    if ( entry->oid_len < MOX_TRUSTEDIP_PREFIX_LEN )
    {
        return 0;
    }
    for ( i = 0; i < MOX_TRUSTEDIP_PREFIX_LEN; i++ )
    {
        if ( (oid) entry->oid_list[i] != mox_trustedip_prefix[i] )
        {
            return 0;
        }
    }
    return 1;
}

static int
mox_snmp_forward_get_to_framework(struct ies_auto_mibs_entry *entry,
                                  netsnmp_agent_request_info *reqinfo,
                                  netsnmp_request_info       *request)
{
    netsnmp_subtree      *sub;
    netsnmp_subtree      *cand;
    netsnmp_request_info *saved_next;

    /* framework registers the table as ONE table_data_set at the TABLE ROOT
     * (mox_trustedip_prefix, .2), while in-master registers the deeper columns
     * (.2.1.c). Searching entry->oid_list (a column) never reaches framework's
     * table subtree — locate it at the table root, which framework owns
     * exclusively. Same-region priority variants are linked via ->children. */
    (void) entry;
    sub = netsnmp_subtree_find(mox_trustedip_prefix, MOX_TRUSTEDIP_PREFIX_LEN,
                               NULL, NULL);
    LibUtil_DbgTrace(kDbgFlgIssUriSNMP,
        "PlanE-DBG: fwd2fw mode=%d subtree_find(.2)=%p\n",
        reqinfo->mode, (void *) sub);
    if ( sub == NULL )
    {
        return -1;
    }
    for ( cand = sub; cand != NULL; cand = cand->children )
    {
        int is_self = ( cand->reginfo != NULL && cand->reginfo->handler != NULL &&
                        cand->reginfo->handler->access_method == mox_snmp_handle_entry );
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP,
            "PlanE-DBG: fwd2fw cand=%p prio=%d self=%d name=%s\n",
            (void *) cand,
            cand->reginfo ? cand->reginfo->priority : -1,
            is_self,
            (cand->reginfo && cand->reginfo->handler && cand->reginfo->handler->handler_name)
                ? cand->reginfo->handler->handler_name : "(null)");
        if ( cand->reginfo != NULL && cand->reginfo->handler != NULL &&
             cand->reginfo->handler->access_method != mox_snmp_handle_entry )
        {
            saved_next    = request->next;
            request->next = NULL;
            (void) netsnmp_call_handlers(cand->reginfo, reqinfo, request);
            request->next = saved_next;
            LibUtil_DbgTrace(kDbgFlgIssUriSNMP,
                "PlanE-DBG: fwd2fw delegated -> processed=%d delegated=%d\n",
                request->processed, request->delegated);
            return 0;
        }
    }
    LibUtil_DbgTrace(kDbgFlgIssUriSNMP,
        "PlanE-DBG: fwd2fw framework reg NOT found\n");
    return -1;                           /* framework subagent not present */
}

