35	/* Plan E fix-1 PoC: register a self-contained read-only table_data_set at `root`
36	 * (the table OID; entry is root.1). Two columns (1=INTEGER, 2=OCTET STRING),
37	 * three rows indexed by INTEGER 1..3. net-snmp's table_data_set helper serves
38	 * GET/GETNEXT/GETBULK entirely — this proves a forwarded walk/bulkwalk into a
39	 * framework-owned table works before we map real config data. Priority 200 so
40	 * in-master (127) still wins the wire (dual-reg). Returns 0 on success. */
41	int
42	MoxaAgentX_RegisterDemoTable(const oid *root, size_t root_len)
43	{
44	    netsnmp_table_data_set       *tds;
45	    netsnmp_handler_registration *reg;
46	    int                           i;
47	
48	    tds = netsnmp_create_table_data_set("moxaDemoTable");
49	    if (tds == NULL)
50	    {
51	        return -1;
52	    }
53	    netsnmp_table_dataset_add_index(tds, ASN_INTEGER);           /* index: INTEGER */
54	    netsnmp_table_set_add_default_row(tds, 1, ASN_INTEGER,   0, NULL, 0);
55	    netsnmp_table_set_add_default_row(tds, 2, ASN_OCTET_STR, 0, NULL, 0);
56	
57	    for (i = 1; i <= 3; i++)
58	    {
59	        netsnmp_table_row *row = netsnmp_create_table_data_row();
60	        long               idx = i;
61	        long               val = i * 10;
62	        char               buf[16];
63	        int                n;
64	
65	        if (row == NULL)
66	        {
67	            return -1;
68	        }
69	        netsnmp_table_row_add_column(row, ASN_INTEGER, &idx, sizeof(idx));   /* index */
70	        netsnmp_set_row_column(row, 1, ASN_INTEGER, (const void *) &val, sizeof(val));
71	        n = snprintf(buf, sizeof(buf), "row-%d", i);
72	        netsnmp_set_row_column(row, 2, ASN_OCTET_STR, (const void *) buf, (size_t) n);
73	        netsnmp_table_dataset_add_row(tds, row);
74	    }
75	
76	    reg = netsnmp_create_handler_registration("moxaDemoTable", NULL,
77	                                              root, root_len, HANDLER_CAN_RONLY);
78	    if (reg == NULL)
79	    {
80	        return -1;
81	    }
82	    reg->priority = 200;
83	    return netsnmp_register_table_data_set(reg, tds, NULL);
84	}
